/* English dataset: 97 key techniques. Mirrors data/atlas.json; no added facts. */
window.TECH_DATA = [{"id":"word2vec","name":"word2vec","zh":"Word Embeddings (word2vec)","year":2013,"category":"Data","cat":"Data","origin":"Google","summary":"Mikolov et al. introduced word embeddings with two architectures, CBOW and Skip-gram, that map words into low-dimensional dense vectors using a shallow neural network. Unlike one-hot encoding, these vectors encode semantic similarity, while negative sampling and hierarchical softmax sharply reduce training cost.","impact":"Made semantic similarity expressible as vector arithmetic and became the word-representation foundation for all later pretrained language models.","source":"https://arxiv.org/abs/1301.3781","models":[],"model_refs":[]},{"id":"adam-adamw","name":"Adam and AdamW Optimizers","zh":"Adam / AdamW","year":2014,"category":"Training","cat":"Training","origin":"Kingma & Ba; Loshchilov & Hutter","summary":"Adam adapts the learning rate per parameter using first- and second-moment estimates; AdamW decouples weight decay from the gradient update, fixing the bias of L2 regularization under adaptive optimizers.","impact":"The default optimizer for Transformers and virtually all LLM pretraining, making large-scale training far less sensitive to hyperparameters.","source":"https://arxiv.org/abs/1412.6980","models":[],"model_refs":[]},{"id":"attention-mechanism","name":"Attention Mechanism","zh":"Attention Mechanism","year":2014,"category":"Architecture","cat":"Architecture","origin":"Research community","summary":"Bahdanau et al. introduced attention in neural machine translation: at each step the decoder aligns to and reads all encoder hidden states by learned weights instead of a single fixed vector, relieving the long-sequence information bottleneck.","impact":"Turned 'focus on demand' into a general neural component and became the core of Transformers and long-context capability.","source":"https://arxiv.org/abs/1409.0473","models":[],"model_refs":[]},{"id":"glove","name":"GloVe: Global Vectors for Word Representation","zh":"GloVe","year":2014,"category":"Data","cat":"Data","origin":"Stanford (Pennington et al.)","summary":"Factorizes a global word-word co-occurrence matrix with weighted least squares, combining the analogy-solving ability of local window methods with global corpus statistics.","impact":"Became a default word representation alongside word2vec and the de facto input embedding for early NLP models.","source":"https://aclanthology.org/D14-1162/","models":[],"model_refs":[]},{"id":"seq2seq","name":"Sequence to Sequence","zh":"Sequence to Sequence","year":2014,"category":"Architecture","cat":"Architecture","origin":"Google","summary":"Sutskever et al. proposed an encoder-decoder architecture for end-to-end sequence transduction: the encoder compresses the input into a fixed vector from which the decoder generates the output. Originally used for machine translation, it handles variable-length inputs and outputs.","impact":"Established the encoder-decoder paradigm and directly preceded attention and the Transformer.","source":"https://arxiv.org/abs/1409.3215","models":[],"model_refs":[]},{"id":"knowledge-distillation","name":"Knowledge Distillation","zh":"Knowledge Distillation","year":2015,"category":"Training","cat":"Training","origin":"Research community","summary":"Hinton et al. proposed training a small model on the soft probability distribution produced by a large one, exploiting the class-similarity information it carries, usually with a temperature parameter. In the LLM era it is also used to transfer chain-of-thought reasoning into smaller models.","impact":"Compresses models with little capability loss; a major source of low-cost deployment and compact open models.","source":"https://arxiv.org/abs/1503.02531","models":["deepseek-r1"],"model_refs":["deepseek-r1"]},{"id":"residual-connection","name":"Residual Connections","zh":"Residual Connections","year":2015,"category":"Architecture","cat":"Architecture","origin":"Microsoft Research (He et al.)","summary":"Rewrites a layer as F(x)+x so gradients flow along an identity path, allowing networks with hundreds of layers to train without degradation.","impact":"Both attention and feed-forward sublayers in Transformers rely on residual connections; they are the prerequisite for ever-deeper LLMs.","source":"https://arxiv.org/abs/1512.03385","models":[],"model_refs":[]},{"id":"gradient-checkpointing","name":"Gradient Checkpointing","zh":"Gradient Checkpointing","year":2016,"category":"Efficiency","cat":"Efficiency","origin":"OpenAI (Chen et al.)","summary":"Stores activations only at a few checkpoints and recomputes the rest during backpropagation, trading extra compute for a near square-root memory saving.","impact":"Allows deep networks to train under limited memory and remains standard for long-context and very large model training.","source":"https://arxiv.org/abs/1604.06174","models":[],"model_refs":[]},{"id":"layer-norm","name":"Layer Normalization","zh":"Layer Normalization","year":2016,"category":"Architecture","cat":"Architecture","origin":"University of Toronto (Ba et al.)","summary":"Normalizes across the feature dimension of a single example rather than over a batch, so it is stable for variable-length sequences and small batches and speeds up convergence.","impact":"A standard component of every Transformer sublayer; its RMSNorm and Pre-LN variants determine whether hundred-layer models train stably.","source":"https://arxiv.org/abs/1607.06450","models":[],"model_refs":[]},{"id":"subword-tokenization","name":"Subword Tokenization (BPE / SentencePiece)","zh":"Subword Tokenization","year":2016,"category":"Data","cat":"Data","origin":"University of Edinburgh (Sennrich et al.); Google (Kudo et al.)","summary":"Rare words are split into frequent subword units; byte-pair encoding or a unigram language model learns the vocabulary from corpus statistics, eliminating unknown tokens under a fixed vocabulary size.","impact":"The tokenization foundation of every mainstream LLM; it determines effective context length, multilingual coverage and how numbers or code are handled.","source":"https://arxiv.org/abs/1508.07909","models":[],"model_refs":[]},{"id":"mixed-precision","name":"Mixed Precision Training","zh":"Mixed Precision Training","year":2017,"category":"Efficiency","cat":"Efficiency","origin":"NVIDIA (Micikevicius et al.)","summary":"Uses FP16 for matmuls and activations while keeping FP32 master weights, with loss scaling to prevent gradient underflow; halves memory and exploits Tensor Cores.","impact":"Made hundred-billion-parameter training feasible on existing GPUs and underpins later FP8 / BF16 training.","source":"https://arxiv.org/abs/1710.03740","models":[],"model_refs":[]},{"id":"moe","name":"Mixture of Experts","zh":"Mixture of Experts","year":2017,"category":"Efficiency","cat":"Efficiency","origin":"Research community","summary":"Sparsely-Gated MoE equips a network with multiple 'expert' subnetworks, with a gate activating only a few per token, decoupling total parameter count from per-token compute. Switch Transformer, Mixtral and the DeepSeek series extended this sparse route.","impact":"Supports trillion-scale total parameters at low inference cost; now the mainstream architecture for frontier open models.","source":"https://arxiv.org/abs/1701.06538","models":["mixtral-8x7b","deepseek-v3","llama-4-maverick"],"model_refs":["mixtral-8x7b","deepseek-v3","llama-4-maverick"]},{"id":"ppo","name":"Proximal Policy Optimization","zh":"Proximal Policy Optimization","year":2017,"category":"Training","cat":"Training","origin":"OpenAI (Schulman et al.)","summary":"An on-policy policy-gradient algorithm that clips the probability-ratio objective to bound policy updates; first-order optimization alone gives TRPO-like stability with far simpler implementation.","impact":"Became the standard optimizer for RLHF, underpinning InstructGPT, ChatGPT and Llama 2-Chat alignment pipelines.","source":"https://arxiv.org/abs/1707.06347","models":["InstructGPT","ChatGPT","Llama 2-Chat"],"model_refs":[]},{"id":"pos-encoding-sinusoidal","name":"Sinusoidal Positional Encoding","zh":"Sinusoidal Positional Encoding","year":2017,"category":"Architecture","cat":"Architecture","origin":"Google (Vaswani et al.)","summary":"Injects absolute position into token vectors with sine and cosine functions at different frequencies; no learned parameters, yet relative offsets remain expressible.","impact":"Opened positional encoding as its own research line, later evolving into relative positions, ALiBi, RoPE and length-extrapolation methods.","source":"https://arxiv.org/abs/1706.03762","models":[],"model_refs":[]},{"id":"transformer","name":"Transformer","zh":"Transformer","year":2017,"category":"Architecture","cat":"Architecture","origin":"Google","summary":"Vaswani et al. proposed in 'Attention Is All You Need' a sequence model built entirely on self-attention, removing recurrence and convolution and combining multi-head attention, positional encoding and feed-forward layers. It trains with high parallelism.","impact":"Became the unified backbone of BERT, GPT and virtually all modern LLMs, sustaining the expansion of parameter scale and context length.","source":"https://arxiv.org/abs/1706.03762","models":["gpt-1","bert","t5"],"model_refs":["gpt-1","bert","t5"]},{"id":"bert-pretraining","name":"BERT Pre-training","zh":"BERT Pre-training","year":2018,"category":"Training","cat":"Training","origin":"Google","summary":"Devlin et al. pretrained a Transformer encoder bidirectionally with masked language modeling, then fine-tuned on downstream tasks. Each word representation depends on both left and right context, and classification, QA and similar tasks share one fine-tuning paradigm.","impact":"Demonstrated the power of large-scale pretraining plus lightweight fine-tuning, opened the pretrained-model race and set new records on many understanding tasks.","source":"https://arxiv.org/abs/1810.04805","models":["bert"],"model_refs":["bert"]},{"id":"elmo","name":"ELMo: Deep Contextualized Word Representations","zh":"ELMo","year":2018,"category":"Training","cat":"Training","origin":"Allen Institute for AI (Peters et al.)","summary":"A bidirectional LSTM language model produces a distinct vector for each word depending on its whole sentence, replacing the one-vector-per-word static embeddings of word2vec. Downstream models combine weighted layers of these representations.","impact":"Made context-dependent word vectors standard and directly set the stage for BERT and the pretrain-then-finetune paradigm.","source":"https://arxiv.org/abs/1802.05365","models":[],"model_refs":[]},{"id":"gpt-autoregressive-pretraining","name":"GPT Autoregressive Pre-training","zh":"GPT Autoregressive Pre-training","year":2018,"category":"Training","cat":"Training","origin":"OpenAI","summary":"Radford et al. proposed generative pretraining: train a decoder-only Transformer to predict the next token, then fine-tune for specific tasks. A single language-modeling objective replaces task-specific architectures.","impact":"Established the decoder-only autoregressive line, the technical starting point for the GPT family and mainstream generative LLMs.","source":"https://cdn.openai.com/research-covers/language-unsupervised/language_understanding_paper.pdf","models":["gpt-1","gpt-2","gpt-3"],"model_refs":["gpt-1","gpt-2","gpt-3"]},{"id":"ulmfit","name":"ULMFiT: Universal Language Model Fine-tuning","zh":"ULMFiT","year":2018,"category":"Training","cat":"Training","origin":"fast.ai (Howard & Ruder)","summary":"A three-stage recipe: pretrain a language model on general text, continue pretraining on the target domain, then fine-tune a classifier with gradual unfreezing and a slanted triangular learning rate. Strong text classification with very few labels.","impact":"Showed pretrained language models transfer to arbitrary downstream tasks; the strongest evidence for pretrain-then-finetune before BERT.","source":"https://arxiv.org/abs/1801.06146","models":[],"model_refs":[]},{"id":"world-model","name":"World Model (LLM-related)","zh":"World Models (LLM-related)","year":2018,"category":"Multimodal","cat":"Multimodal","origin":"Ha & Schmidhuber (2018); LLM integrations: LLM-DM (NeurIPS 2023), WorldGPT (2024), OpenAI Sora (2024)","summary":"A model learns environment transition dynamics to predict the next state and plan accordingly; combined with LLMs, language models build or serve as implicit world models or generative world simulators.","impact":"Seen as a key direction beyond pure token prediction, giving models physical common sense and planning ability.","source":"https://arxiv.org/abs/1803.10122","models":["LLM-DM","WorldGPT","Sora"],"model_refs":[]},{"id":"adapter-modules","name":"Adapter Modules","zh":"Adapter Modules","year":2019,"category":"Efficiency","cat":"Efficiency","origin":"Google / DeepMind (Houlsby et al.)","summary":"Inserts small bottleneck feed-forward networks between Transformer layers; fine-tuning updates only these modules, keeping one few-megabyte adapter per task.","impact":"First systematic demonstration that a frozen backbone plus small modules works; the direct predecessor of PEFT and model reuse.","source":"https://arxiv.org/abs/1902.00751","models":[],"model_refs":[]},{"id":"bart","name":"BART: Denoising Sequence-to-Sequence Pre-training","zh":"BART","year":2019,"category":"Training","cat":"Training","origin":"Meta AI (Lewis et al.)","summary":"Corrupts text with arbitrary noising functions (sentence shuffling, deletion, span masking) and trains a sequence-to-sequence model to reconstruct it, combining bidirectional understanding with autoregressive generation.","impact":"Established the encoder-decoder pretraining route for generation (summarization, dialogue, translation) and underpinned early RAG generators.","source":"https://arxiv.org/abs/1910.13461","models":[],"model_refs":[]},{"id":"rmsnorm-swiglu","name":"RMSNorm and SwiGLU","zh":"RMSNorm & SwiGLU","year":2019,"category":"Architecture","cat":"Architecture","origin":"Zhang & Sennrich; Google (Shazeer)","summary":"RMSNorm rescales by root-mean-square without mean centering; SwiGLU replaces the feed-forward activation with a gated linear unit. Both are cheaper and empirically stronger.","impact":"The standard component pair in LLaMA, Qwen, DeepSeek, PaLM and most modern open architectures.","source":"https://arxiv.org/abs/1910.07467","models":[],"model_refs":[]},{"id":"roberta","name":"RoBERTa: Robustly Optimized BERT","zh":"RoBERTa","year":2019,"category":"Training","cat":"Training","origin":"Meta AI (Liu et al.)","summary":"A systematic ablation of BERT: larger batches, more data and longer training, dynamic masking and dropping next-sentence prediction all help, showing BERT was undertrained.","impact":"Made the training recipe itself an object of study and shaped the data/compute ratios of every later pretrained model.","source":"https://arxiv.org/abs/1907.11692","models":[],"model_refs":[]},{"id":"t5","name":"T5: Text-to-Text Transfer Transformer","zh":"T5","year":2019,"category":"Training","cat":"Training","origin":"Google (Raffel et al.)","summary":"Recasts classification, QA, translation and summarization as text-to-text, pretrains one encoder-decoder with a span-corruption objective, and releases the C4 corpus.","impact":"Unified the multitask fine-tuning interface and provided a reproducible large-scale transfer baseline; C4 became a standard open pretraining corpus.","source":"https://arxiv.org/abs/1910.10683","models":[],"model_refs":[]},{"id":"parallel-training","name":"Tensor, Pipeline and ZeRO Parallelism","zh":"3D Parallelism & ZeRO","year":2019,"category":"Efficiency","cat":"Efficiency","origin":"NVIDIA / Google / Microsoft (Shoeybi, Huang, Rajbhandari et al.)","summary":"Splits matrices within layers (tensor parallel), pipelines layers across devices, or shards optimizer states, gradients and parameters with ZeRO to break the single-GPU memory ceiling.","impact":"Forms 3D-parallel training frameworks; the engineering prerequisite for GPT-3, BLOOM, Megatron-Turing and other very large models.","source":"https://arxiv.org/abs/1910.02054","models":[],"model_refs":[]},{"id":"dpr","name":"Dense Passage Retrieval","zh":"Dense Passage Retrieval","year":2020,"category":"Retrieval","cat":"Retrieval","origin":"Facebook AI (Karpukhin et al.)","summary":"A dual encoder maps questions and passages into one vector space; inner-product retrieval replaces BM25 lexical matching, trained with in-batch negatives.","impact":"The retrieval substrate of modern RAG, moving open-domain QA from keyword to semantic matching.","source":"https://arxiv.org/abs/2004.04906","models":[],"model_refs":[]},{"id":"electra","name":"ELECTRA: Replaced-Token Detection","zh":"ELECTRA","year":2020,"category":"Training","cat":"Training","origin":"Stanford / Google (Clark et al.)","summary":"A small generator replaces some tokens and a discriminator decides per position whether each token was replaced, so every token contributes to the loss instead of only the 15% masked.","impact":"Greatly improved pretraining efficiency at equal compute, showing discriminative objectives can be cheaper than masked language modeling.","source":"https://arxiv.org/abs/2003.10555","models":[],"model_refs":[]},{"id":"in-context-learning","name":"In-Context Learning and Few-Shot Prompting","zh":"In-Context Learning","year":2020,"category":"Reasoning","cat":"Reasoning","origin":"OpenAI (Brown et al., GPT-3)","summary":"With no parameter updates, a handful of input-output examples in the prompt lets the model follow the demonstrated pattern on a new task; the ability grows with scale.","impact":"Turned the prompt into an inference interface and gave rise to prompt engineering, instruction tuning and much of alignment research.","source":"https://arxiv.org/abs/2005.14165","models":[],"model_refs":[]},{"id":"mmlu-helm","name":"MMLU and HELM Holistic Evaluation","zh":"MMLU & HELM","year":2020,"category":"Evaluation","cat":"Evaluation","origin":"UC Berkeley et al. (Hendrycks); Stanford (Liang et al.)","summary":"MMLU measures knowledge and reasoning with multiple-choice questions across 57 subjects; HELM records accuracy, calibration, robustness, fairness and toxicity in one unified scenario suite.","impact":"Established the multi-dimensional, reproducible evaluation paradigm that replaced single-accuracy leaderboards.","source":"https://arxiv.org/abs/2009.03300","models":[],"model_refs":[]},{"id":"pretraining-corpus","name":"Open Pretraining Corpora (C4 / The Pile / FineWeb / Dolma)","zh":"Open Pretraining Corpora","year":2020,"category":"Data","cat":"Data","origin":"Google / EleutherAI / Hugging Face / AI2","summary":"Builds reproducible large-scale corpora from web crawl, heuristic filtering, language ID, deduplication and quality scoring, with sources and pipelines published openly.","impact":"Gave open models training data comparable to closed ones and made the data recipe a first-class determinant of model capability.","source":"https://arxiv.org/abs/2101.00027","models":[],"model_refs":[]},{"id":"rag","name":"Retrieval-Augmented Generation","zh":"Retrieval-Augmented Generation","year":2020,"category":"Retrieval","cat":"Retrieval","origin":"Research community","summary":"Lewis et al. retrieve relevant documents from an external knowledge base before generation and pass them to the model as context. Parameters supply language ability while knowledge can be updated through the index at any time.","impact":"Mitigates hallucination and stale knowledge without retraining; now the mainstream architecture for enterprise question answering.","source":"https://arxiv.org/abs/2005.11401","models":[],"model_refs":[]},{"id":"scaling-laws","name":"Scaling Laws","zh":"Scaling Laws","year":2020,"category":"Training","cat":"Training","origin":"OpenAI","summary":"Kaplan et al. found language-model loss falls as a power law in parameters, data and compute, predictable across orders of magnitude. DeepMind's 2022 Chinchilla work further showed earlier models were systematically undertrained and gave an approximately optimal parameter/data ratio.","impact":"Turned model capability into a predictable, plannable investment problem and directly drove the subsequent parameter and compute race.","source":"https://arxiv.org/abs/2001.08361","models":["gpt-3"],"model_refs":["gpt-3"]},{"id":"sparse-attention","name":"Sparse Attention","zh":"Sparse Attention","year":2020,"category":"Efficiency","cat":"Efficiency","origin":"Research community","summary":"Longformer, BigBird and others let each token attend only to a local window plus a few global positions, reducing attention from quadratic to near-linear in sequence length. DeepSeek adopts DSA and related sparse attention in V3.2/V4 to support ultra-long context.","impact":"Breaks the memory and compute bottleneck of long sequences; a prerequisite for million-token context.","source":"https://arxiv.org/abs/2004.05150","models":["deepseek-v3-2","deepseek-v4"],"model_refs":["deepseek-v3-2","deepseek-v4"]},{"id":"vit","name":"Vision Transformer (ViT)","zh":"Vision Transformer","year":2020,"category":"Multimodal","cat":"Multimodal","origin":"Google (Dosovitskiy et al.)","summary":"Splits an image into fixed-size patches and feeds them as a sequence to a standard Transformer encoder, replacing convolutions as the visual backbone at sufficient data scale.","impact":"Allowed vision and language to share one architecture; the structural prerequisite for unified multimodal modeling.","source":"https://arxiv.org/abs/2010.11929","models":[],"model_refs":[]},{"id":"alibi","name":"ALiBi: Attention with Linear Biases","zh":"ALiBi","year":2021,"category":"Architecture","cat":"Architecture","origin":"University of Washington / Meta (Press et al.)","summary":"Instead of position embeddings, subtracts a head-specific linear penalty from attention scores proportional to query-key distance, so models trained on short sequences extrapolate to longer ones.","impact":"Opened the train-short-test-long extrapolation line and remains a mainstream alternative to RoPE.","source":"https://arxiv.org/abs/2108.12409","models":[],"model_refs":[]},{"id":"clip","name":"CLIP: Contrastive Language-Image Pre-training","zh":"CLIP","year":2021,"category":"Multimodal","cat":"Multimodal","origin":"OpenAI (Radford et al.)","summary":"Contrastive learning on 400M image-text pairs maps images and text into a shared space, so zero-shot classification only needs class names written as natural-language prompts.","impact":"Set the alignment paradigm for multimodal LLMs; the shared foundation of LLaVA, Flamingo, text conditioning in diffusion models and visual instruction tuning.","source":"https://arxiv.org/abs/2103.00020","models":[],"model_refs":[]},{"id":"gsm8k-humaneval","name":"GSM8K and HumanEval","zh":"GSM8K & HumanEval","year":2021,"category":"Evaluation","cat":"Evaluation","origin":"OpenAI (Cobbe, Chen et al.)","summary":"GSM8K supplies grade-school math problems requiring multi-step arithmetic with worked solutions; HumanEval scores code generation automatically with unit tests, avoiding ambiguous string matching.","impact":"Became the standard benchmarks for math reasoning and code generation respectively; progress in chain-of-thought, self-consistency, PRMs and RLVR is measured on them.","source":"https://arxiv.org/abs/2110.14168","models":[],"model_refs":[]},{"id":"instruction-tuning","name":"Instruction Tuning","zh":"Instruction Tuning","year":2021,"category":"Alignment","cat":"Alignment","origin":"Google","summary":"Wei et al. proposed FLAN: rewrite many NLP datasets into natural-language instructions for fine-tuning, improving zero-shot performance on unseen tasks. Self-Instruct and FLAN-T5 later scaled instruction data further.","impact":"Taught models to follow instructions rather than merely continue text; now a standard stage in general-purpose assistant training.","source":"https://arxiv.org/abs/2109.01652","models":["t5","instructgpt"],"model_refs":["t5","instructgpt"]},{"id":"lora-qlora","name":"LoRA / QLoRA","zh":"LoRA / QLoRA","year":2021,"category":"Efficiency","cat":"Efficiency","origin":"Research community","summary":"LoRA freezes pretrained weights and injects trainable low-rank decomposition matrices into Transformer layers, cutting trainable parameters by orders of magnitude. QLoRA further quantizes the base model to 4 bits before fine-tuning, enabling adaptation on a single consumer GPU.","impact":"Moved LLM fine-tuning from compute-intensive to affordable for ordinary developers, greatly expanding the open ecosystem.","source":"https://arxiv.org/abs/2106.09685","models":[],"model_refs":[]},{"id":"prefix-tuning","name":"Prefix-Tuning and Prompt Tuning","zh":"Prefix-Tuning and Prompt Tuning","year":2021,"category":"Efficiency","cat":"Efficiency","origin":"Stanford (Li & Liang); Google (Lester et al.)","summary":"Freezes the whole model and trains only a short learned continuous prefix prepended to keys and values at each layer (or a soft prompt at the input), adapting to tasks with a tiny parameter budget.","impact":"The start of parameter-efficient fine-tuning (PEFT), paving the way for LoRA and multi-task serving at scale.","source":"https://arxiv.org/abs/2101.00190","models":[],"model_refs":[]},{"id":"rope","name":"RoPE","zh":"Rotary Position Embedding (RoPE)","year":2021,"category":"Architecture","cat":"Architecture","origin":"Research community","summary":"Su et al. proposed rotary position embeddings: rotation matrices of different frequencies act on queries and keys so attention scores naturally carry relative position information. The implementation is simple and amenable to length extrapolation.","impact":"Became the default position encoding for LLaMA, Qwen, DeepSeek and most modern LLMs.","source":"https://arxiv.org/abs/2104.09864","models":["llama-1","qwen2","deepseek-v3"],"model_refs":["llama-1","qwen2","deepseek-v3"]},{"id":"data-dedup","name":"Training Data Deduplication","zh":"Training Data Deduplication","year":2021,"category":"Data","cat":"Data","origin":"Google (Lee et al.)","summary":"Detects and removes near-duplicate documents with MinHash or suffix-array approximations, reducing verbatim memorization of repeated text.","impact":"Cuts memorization and privacy risk while improving generalization; now a standard step in every open pretraining corpus.","source":"https://arxiv.org/abs/2107.06499","models":[],"model_refs":[]},{"id":"agent-tool-use","name":"Agent / Tool Use","zh":"Agents and Tool Use","year":2022,"category":"Agents","cat":"Agents","origin":"Research community","summary":"ReAct alternates reasoning with calls to external tools such as search and calculators; OpenAI function calling, the MCP protocol and models like o3 later productized this pattern. Models moved from only answering to executing multi-step tasks.","impact":"Turns language models into agents that call software and operate environments, broadening the application boundary of LLMs.","source":"https://arxiv.org/abs/2210.03629","models":["o3","claude-sonnet-4"],"model_refs":["o3","claude-sonnet-4"]},{"id":"chain-of-thought","name":"Chain-of-Thought","zh":"Chain-of-Thought","year":2022,"category":"Reasoning","cat":"Reasoning","origin":"Google","summary":"Wei et al. supplied few-shot examples containing intermediate reasoning steps, prompting models to write out their reasoning before answering. A handful of examples substantially improved math, commonsense and symbolic reasoning.","impact":"Made 'thinking a few more steps at test time' an operational prompting technique; the origin of later reasoning models and test-time compute.","source":"https://arxiv.org/abs/2201.11903","models":["palm","gpt-3"],"model_refs":["palm","gpt-3"]},{"id":"chinchilla","name":"Chinchilla Compute-Optimal Training","zh":"Chinchilla Scaling","year":2022,"category":"Training","cat":"Training","origin":"DeepMind (Hoffmann et al.)","summary":"Jointly sweeps parameter count and training tokens at fixed compute and finds they should scale roughly proportionally; a smaller model trained longer achieves lower loss at equal compute.","impact":"Corrected the parameter-only scaling race and changed compute allocation for every frontier model after GPT-4.","source":"https://arxiv.org/abs/2203.15556","models":[],"model_refs":[]},{"id":"constitutional-ai","name":"Constitutional AI","zh":"Constitutional AI","year":2022,"category":"Alignment","cat":"Alignment","origin":"Anthropic","summary":"Anthropic proposed having a model critique and revise its own outputs against a written set of principles, generating preference data (RLAIF) to reduce reliance on human harmfulness labels. A key training method for the Claude family.","impact":"Provides an auditable, scalable alignment path complementary to RLHF.","source":"https://arxiv.org/abs/2212.08073","models":["claude-1","claude-2"],"model_refs":["claude-1","claude-2"]},{"id":"continuous-batching","name":"Continuous Batching for LLM Serving","zh":"Continuous Batching","year":2022,"category":"Efficiency","cat":"Efficiency","origin":"KAIST / FriendliAI (Yu et al., Orca)","summary":"Replaces request-level batching with iteration-level scheduling: finished sequences release slots immediately and new requests join at any step, combined with paged KV cache for much higher GPU utilization.","impact":"Established the scheduling model of vLLM, TGI and other modern serving engines, directly determining per-token serving cost.","source":"https://www.usenix.org/conference/osdi22/presentation/yu","models":[],"model_refs":[]},{"id":"flamingo","name":"Flamingo","zh":"Flamingo","year":2022,"category":"Multimodal","cat":"Multimodal","origin":"DeepMind (Alayrac et al.)","summary":"Gated cross-attention connects a frozen vision encoder to a frozen language model; only the bridge is trained, and interleaved image-text sequences enable few-shot in-context learning.","impact":"Showed multimodal ability can be obtained with a lightweight bridge, avoiding the enormous cost of joint pretraining.","source":"https://arxiv.org/abs/2204.14198","models":[],"model_refs":[]},{"id":"flash-attention","name":"FlashAttention","zh":"FlashAttention","year":2022,"category":"Efficiency","cat":"Efficiency","origin":"Research community","summary":"Dao et al. proposed an IO-aware exact attention algorithm that tiles computation to avoid materializing the attention matrix in HBM, substantially cutting memory use and speeding up training with exact results.","impact":"A standard kernel in training and inference frameworks; infrastructure for long context and large-scale training efficiency.","source":"https://arxiv.org/abs/2205.14135","models":[],"model_refs":[]},{"id":"least-to-most","name":"Least-to-Most Prompting","zh":"Least-to-Most Prompting","year":2022,"category":"Reasoning","cat":"Reasoning","origin":"Google (Zhou et al.)","summary":"Decomposes a hard problem into an ordered sequence of subproblems, solves them from easy to hard, and explicitly carries earlier answers into later prompts so the model need not complete the whole reasoning in one pass.","impact":"Makes decomposition explicit and improves compositional generalization; the prototype of later planning-style prompting.","source":"https://arxiv.org/abs/2205.10625","models":[],"model_refs":[]},{"id":"model-merging","name":"Model Merging and Task Arithmetic","zh":"Model Merging and Task Arithmetic","year":2022,"category":"Training","cat":"Training","origin":"University of Washington (Ilharco et al.)","summary":"Treats the weight difference before and after fine-tuning as a task vector; adding, subtracting or linearly combining these vectors merges capabilities without retraining or access to original data.","impact":"A common open-source technique for composing capabilities and building strong baselines, later extended by TIES, DARE and other interference-resolution methods.","source":"https://arxiv.org/abs/2212.04089","models":[],"model_refs":[]},{"id":"orm","name":"Outcome Reward Model","zh":"Outcome Reward Model","year":2022,"category":"Alignment","cat":"Alignment","origin":"DeepMind (Uesato et al.)","summary":"A verifier trained only on whether the final answer is correct (ORM). Compared with step-level PRMs it is more label-efficient but prone to 'right answer, wrong reasoning'.","impact":"Established the process-vs-outcome supervision framework and the conceptual starting point for PRM and RLVR reward work.","source":"https://arxiv.org/abs/2211.14275","models":[],"model_refs":[]},{"id":"quantization","name":"Quantization (GPTQ/AWQ/GGUF)","zh":"Model Quantization (GPTQ/AWQ/GGUF)","year":2022,"category":"Efficiency","cat":"Efficiency","origin":"Research community","summary":"Weights are compressed from FP16 to INT8/INT4 to save memory and bandwidth. GPTQ and AWQ are typical post-training quantization methods; GGUF is the llama.cpp file format that makes loading quantized models easy on consumer hardware.","impact":"Lets tens-of-billions-parameter models run on a single GPU or a personal computer; a key driver of open-model adoption.","source":"https://arxiv.org/abs/2210.17323","models":[],"model_refs":[]},{"id":"rlhf","name":"RLHF","zh":"RLHF","year":2022,"category":"Alignment","cat":"Alignment","origin":"OpenAI","summary":"Ouyang et al. proposed a three-stage alignment pipeline: supervised fine-tuning, training a reward model on human preference comparisons, then optimizing outputs with reinforcement learning. In InstructGPT a 1.3B model outperformed the 175B GPT-3 on human preference ratings.","impact":"Brought 'helpful, honest, harmless' human preferences into the training objective; the key technique that made ChatGPT usable.","source":"https://arxiv.org/abs/2203.02155","models":["instructgpt","chatgpt"],"model_refs":["instructgpt","chatgpt"]},{"id":"red-teaming","name":"Red Teaming and Jailbreak Discovery","zh":"Red Teaming","year":2022,"category":"Evaluation","cat":"Evaluation","origin":"Anthropic / DeepMind (Perez et al.)","summary":"Language models generate large numbers of adversarial prompts to systematically surface harmful outputs, jailbreaks and prompt injection, feeding discovered failures back into safety training.","impact":"Turned safety evaluation from manual sampling into scalable automatic generation; now a standard pre-release safety stage.","source":"https://arxiv.org/abs/2202.03286","models":[],"model_refs":[]},{"id":"rlaif","name":"Reinforcement Learning from AI Feedback","zh":"RL from AI Feedback","year":2022,"category":"Alignment","cat":"Alignment","origin":"Anthropic (introduced in Constitutional AI); Google (dedicated 2023 study)","summary":"An AI model scores pairs of answers against written principles to generate preference data and train a reward model, which is then used for RL — greatly reducing human annotation.","impact":"Freed alignment from the human-labeling bottleneck; the basis of the Claude series and scalable-alignment research.","source":"https://arxiv.org/abs/2212.08073","models":["Claude","PaLM（Google RLAIF 研究）"],"model_refs":[]},{"id":"reward-overoptimization","name":"Reward Model Overoptimization","zh":"Reward Model Overoptimization","year":2022,"category":"Evaluation","cat":"Evaluation","origin":"OpenAI (Gao et al.)","summary":"Measures how true quality first rises then falls as RL optimizes a proxy reward, and characterizes the scaling with KL budget and reward-model size.","impact":"Established the key failure mode and diagnostics for RLHF; the starting point for KL regularization, length penalties and judge calibration.","source":"https://arxiv.org/abs/2210.10760","models":[],"model_refs":[]},{"id":"self-consistency","name":"Self-Consistency","zh":"Self-Consistency","year":2022,"category":"Reasoning","cat":"Reasoning","origin":"Google (Wang et al.)","summary":"Samples multiple distinct chains of thought for one question and majority-votes over final answers instead of greedily decoding a single path.","impact":"Improved math and commonsense reasoning at very low cost; one of the earliest practical forms of test-time compute.","source":"https://arxiv.org/abs/2203.11171","models":[],"model_refs":[]},{"id":"self-instruct","name":"Self-Instruct","zh":"Self-Instruct","year":2022,"category":"Data","cat":"Data","origin":"University of Washington et al. (Wang et al.)","summary":"Uses a few seed instructions to have the model generate new tasks, filters them, and fine-tunes on the result instead of relying on human-written instructions.","impact":"Started the model-generates-data-for-models line; the direct source of Alpaca, Vicuna and other open instruction models.","source":"https://arxiv.org/abs/2212.10560","models":[],"model_refs":[]},{"id":"speculative-decoding","name":"Speculative Decoding","zh":"Speculative Decoding","year":2022,"category":"Reasoning","cat":"Reasoning","origin":"Research community","summary":"A small model quickly drafts several tokens and the large model verifies them in parallel, accepting correct ones and correcting wrong ones — faster generation without changing the output distribution.","impact":"Reduces inference latency without quality loss; widely integrated into serving frameworks.","source":"https://arxiv.org/abs/2211.17192","models":[],"model_refs":[]},{"id":"sft","name":"Supervised Fine-Tuning","zh":"Supervised Fine-Tuning","year":2022,"category":"Training","cat":"Training","origin":"OpenAI","summary":"Fine-tune a pretrained model in a supervised fashion on high-quality human-demonstrated QA pairs; the first step (SFT) of the InstructGPT/ChatGPT alignment pipeline.","impact":"Turns a base model that only continues text into an instruction-following assistant; the starting point for nearly all later alignment methods.","source":"https://arxiv.org/abs/2203.02155","models":["InstructGPT","ChatGPT"],"model_refs":[]},{"id":"synthetic-data","name":"Synthetic Data","zh":"Synthetic Data","year":2022,"category":"Data","cat":"Data","origin":"Research community","summary":"Self-Instruct and related work have models generate instruction-response pairs, filter them and use them for fine-tuning, alleviating the shortage of high-quality human annotation. Since then widely used for instruction data augmentation and math/code training.","impact":"Shifted data production from purely human to 'model generation + filtering', sharply lowering the cost of alignment and domain models.","source":"https://arxiv.org/abs/2212.10560","models":[],"model_refs":[]},{"id":"zero-shot-cot","name":"Zero-Shot Chain-of-Thought","zh":"Zero-Shot Chain-of-Thought","year":2022,"category":"Reasoning","cat":"Reasoning","origin":"Google / University of Tokyo (Kojima et al.)","summary":"Adding a single phrase such as 'Let's think step by step' elicits intermediate reasoning without any worked examples.","impact":"Showed reasoning can be activated by a prompt alone, making chain-of-thought a zero-setup general technique.","source":"https://arxiv.org/abs/2205.11916","models":[],"model_refs":[]},{"id":"dpo","name":"DPO","zh":"Direct Preference Optimization","year":2023,"category":"Alignment","cat":"Alignment","origin":"Research community","summary":"Rafailov et al. optimize the policy directly from preference pairs, expressing the reward implicitly as the ratio between policy and reference model, removing the explicit reward model and online RL. Training is simpler and more stable.","impact":"Greatly lowered the barrier and cost of preference alignment; one of the most widely used methods in the open-source community.","source":"https://arxiv.org/abs/2305.18290","models":[],"model_refs":[]},{"id":"ipo","name":"IPO: Identity Preference Optimization","zh":"IPO","year":2023,"category":"Alignment","cat":"Alignment","origin":"DeepMind (Azar et al.)","summary":"Shows theoretically that DPO overfits when preference data is separable and proposes optimizing an identity on preference probabilities with regularization, yielding a unified framework.","impact":"Provides the theoretical diagnosis and improvement direction for DPO and its variants; the theory anchor of the preference-optimization family.","source":"https://arxiv.org/abs/2310.12036","models":[],"model_refs":[]},{"id":"kv-cache-paged-attention","name":"KV Cache / PagedAttention","zh":"KV Cache and PagedAttention","year":2023,"category":"Efficiency","cat":"Efficiency","origin":"Research community","summary":"vLLM introduced PagedAttention, managing KV cache with operating-system-style paging to reduce memory fragmentation and enable efficient sharing, substantially improving multi-request throughput.","impact":"Laid the foundation for modern LLM serving engines and directly reduced per-token serving cost.","source":"https://arxiv.org/abs/2309.06180","models":[],"model_refs":[]},{"id":"llm-as-judge","name":"LLM-as-a-Judge and MT-Bench","zh":"LLM-as-a-Judge and MT-Bench","year":2023,"category":"Evaluation","cat":"Evaluation","origin":"UC Berkeley / UCSD / CMU (Zheng et al.)","summary":"A strong model judges open-ended answers by pairwise comparison or scoring; MT-Bench and Chatbot Arena human preferences validate agreement, while position bias, verbosity bias and self-preference bias are characterized.","impact":"Made automatic evaluation of open-ended generation feasible and became shared infrastructure for alignment, reward modeling and model selection, while turning judge bias into its own research problem.","source":"https://arxiv.org/abs/2306.05685","models":[],"model_refs":[]},{"id":"llava","name":"LLaVA: Visual Instruction Tuning","zh":"LLaVA","year":2023,"category":"Multimodal","cat":"Multimodal","origin":"Microsoft Research / University of Wisconsin (Liu et al.)","summary":"Uses GPT-4 to turn image captions and bounding boxes into conversational instruction data, then fine-tunes a vision encoder, projection layer and LLM into an assistant that answers questions about images.","impact":"Reproduced multimodal dialogue at very low cost and became the mainstream recipe for open vision-language models.","source":"https://arxiv.org/abs/2304.08485","models":[],"model_refs":[]},{"id":"mamba-ssm","name":"Mamba / State Space Models","zh":"Mamba / State Space Models","year":2023,"category":"Architecture","cat":"Architecture","origin":"Research community","summary":"Mamba adds input-dependent selection and hardware-aware algorithms to structured state space models, achieving linear-complexity inference while retaining long-range dependency modeling.","impact":"One of the main alternatives to Transformers, adopted by hybrid architectures such as Jamba, advancing efficient sequence modeling.","source":"https://arxiv.org/abs/2312.00752","models":["jamba"],"model_refs":["jamba"]},{"id":"multi-agent","name":"Multi-Agent / Agentic Workflow","zh":"Multi-Agent / Agentic Workflow","year":2023,"category":"Agents","cat":"Agents","origin":"DeepWisdom (MetaGPT); Microsoft (AutoGen); CAMEL et al.","summary":"LLM agents with different roles are organized by standard operating procedures or conversation graphs to collaborate on complex tasks; MetaGPT, for example, simulates a software company and produces complete code.","impact":"Role specialization and structured deliverables reduce hallucination and improve reliability on complex tasks; a mainstream form of agent engineering.","source":"https://arxiv.org/abs/2308.00352","models":["MetaGPT","AutoGen","CAMEL"],"model_refs":[]},{"id":"gqa-mqa","name":"Multi-Query and Grouped-Query Attention","zh":"MQA / GQA","year":2023,"category":"Efficiency","cat":"Efficiency","origin":"Google (Shazeer; Ainslie et al.)","summary":"Multiple query heads share one key/value head (MQA) or share within groups (GQA), cutting KV cache and decode bandwidth several-fold with little quality loss.","impact":"The default configuration for long-context inference in Llama 2/3, Qwen, Mistral and other open models.","source":"https://arxiv.org/abs/2305.13245","models":[],"model_refs":[]},{"id":"multimodal-fusion","name":"Multimodal Fusion","zh":"Multimodal Fusion","year":2023,"category":"Multimodal","cat":"Multimodal","origin":"OpenAI","summary":"Text, images and audio are encoded into a shared representation space or handled by a single model. CLIP aligns image and text with contrastive learning; GPT-4V and GPT-4o accept image and audio input within one model with low-latency voice interaction.","impact":"Gave language models sight and hearing, extending the chat interface into a natively multimodal assistant.","source":"https://arxiv.org/abs/2303.08774","models":["gpt-4","gpt-4o","gemini-1-0-ultra"],"model_refs":["gpt-4","gpt-4o","gemini-1-0-ultra"]},{"id":"position-interpolation","name":"Position Interpolation","zh":"Position Interpolation","year":2023,"category":"Efficiency","cat":"Efficiency","origin":"Meta AI (Chen et al.)","summary":"Rescales position indices of a long sequence back into the model's original range, extending a RoPE model's context window several-fold with only light fine-tuning.","impact":"Started the long-context race at very low cost; the origin of YaRN, LongRoPE and production million-token context.","source":"https://arxiv.org/abs/2306.15595","models":[],"model_refs":[]},{"id":"prm","name":"Process Reward Model","zh":"Process Reward Model","year":2023,"category":"Alignment","cat":"Alignment","origin":"OpenAI (Lightman et al.); concept from DeepMind, Uesato et al. 2022","summary":"A verifier that scores each step of a reasoning chain rather than only the final answer. 'Let's Verify Step by Step' showed process supervision substantially outperforms outcome supervision and released PRM800K.","impact":"Can locate errors mid-reasoning and guide search; a key component of test-time compute in o1/R1-style reasoning models.","source":"https://arxiv.org/abs/2305.20050","models":["GPT-4 验证器","PRM800K"],"model_refs":[]},{"id":"reflection","name":"Reflection / Self-Correction","zh":"Reflection / Self-Correction","year":2023,"category":"Agents","cat":"Agents","origin":"Northeastern University / MIT / Princeton (Shinn et al.)","summary":"Reflexion has an agent write a natural-language self-critique after failure, store it in episodic memory and use it to improve the next attempt — without updating model weights.","impact":"Moved self-improvement from training to inference; the basis of the modern agent 'think–check–retry' loop.","source":"https://arxiv.org/abs/2303.11366","models":[],"model_refs":[]},{"id":"rejection-sampling","name":"Rejection Sampling / Best-of-N","zh":"Rejection Sampling / Best-of-N","year":2023,"category":"Training","cat":"Training","origin":"Alibaba DAMO Academy (RFT, Yuan et al.); related to STaR 2022 and RAFT 2023","summary":"Sample multiple responses per prompt and keep only those with correct answers or the highest reward for supervised fine-tuning (RFT/RAFT), optionally iterated.","impact":"Improves reasoning and alignment from a model's own successful samples without RL; part of production pipelines for Llama 3 and DeepSeek-R1.","source":"https://arxiv.org/abs/2308.01825","models":["Llama 3","DeepSeek-R1"],"model_refs":[]},{"id":"ring-attention","name":"Ring Attention","zh":"Ring Attention","year":2023,"category":"Efficiency","cat":"Efficiency","origin":"UC Berkeley (Liu et al.)","summary":"Shards a sequence across devices and overlaps blockwise attention with all-gather communication in a ring, so context length grows near-linearly with device count at constant per-device memory.","impact":"Made million-token context training engineering-feasible; the representative scheme for distributed long-sequence attention.","source":"https://arxiv.org/abs/2310.01889","models":[],"model_refs":[]},{"id":"swe-bench","name":"SWE-bench","zh":"SWE-bench","year":2023,"category":"Evaluation","cat":"Evaluation","origin":"Princeton / University of Chicago (Jimenez et al.)","summary":"Builds tasks from real GitHub issues and their patches, requiring an agent to localize, edit and pass tests inside a full repository, scored automatically by test pass rate.","impact":"Moved evaluation from isolated function synthesis to repository-level software engineering and became the main yardstick for coding agents.","source":"https://arxiv.org/abs/2310.06770","models":[],"model_refs":[]},{"id":"self-rag","name":"Self-RAG","zh":"Self-RAG","year":2023,"category":"Retrieval","cat":"Retrieval","origin":"University of Washington / AI2 (Asai et al.)","summary":"The model emits reflection tokens deciding when to retrieve, whether passages are relevant and whether its output is supported by evidence, enabling on-demand retrieval and self-critique.","impact":"Turned retrieval from a fixed preprocessing step into a model-controlled decision; a key step toward agentic RAG.","source":"https://arxiv.org/abs/2310.11511","models":[],"model_refs":[]},{"id":"streamingllm","name":"StreamingLLM","zh":"StreamingLLM","year":2023,"category":"Efficiency","cat":"Efficiency","origin":"MIT / CMU (Xiao et al.)","summary":"Identifies attention sinks: keeping the first few tokens' KV plus a recent sliding window allows stable processing of unbounded streaming input under a fixed cache budget.","impact":"Explains why plain window attention fails and provides a streaming inference solution requiring no retraining.","source":"https://arxiv.org/abs/2309.17453","models":[],"model_refs":[]},{"id":"tir","name":"Tool-Integrated Reasoning","zh":"Tool-Integrated Reasoning","year":2023,"category":"Reasoning","cat":"Reasoning","origin":"Microsoft Research Asia / Tsinghua University (ToRA, Gou et al.)","summary":"Interleave calls to code interpreters and symbolic solvers into natural-language reasoning, using execution results to guide subsequent steps (ToRA is a representative work).","impact":"Breaks the arithmetic and symbolic limits of pure text models; a common paradigm for math reasoning and coding agents.","source":"https://arxiv.org/abs/2309.17452","models":["ToRA","Qwen2.5-Math（TIR 模式）"],"model_refs":[]},{"id":"toolformer","name":"Toolformer","zh":"Toolformer","year":2023,"category":"Agents","cat":"Agents","origin":"Meta AI (Schick et al.)","summary":"The model samples API calls inside text, executes them, and keeps only calls that reduce loss on following tokens, self-supervising when to use a calculator, search or calendar.","impact":"Turned tool use from hand-written prompting into a learned capability; an important precursor to function calling and agent training.","source":"https://arxiv.org/abs/2302.04761","models":[],"model_refs":[]},{"id":"tree-of-thoughts","name":"Tree of Thoughts","zh":"Tree of Thoughts","year":2023,"category":"Reasoning","cat":"Reasoning","origin":"Princeton / Google DeepMind (Yao et al.)","summary":"Expands reasoning states into a tree, scores branches with self-evaluation, and explores or backtracks with BFS/DFS.","impact":"Brought classical search into LLM reasoning; the representative work on inference-time search before o1/R1.","source":"https://arxiv.org/abs/2305.10601","models":[],"model_refs":[]},{"id":"long-context-yarn","name":"YaRN / Long Context","zh":"Long Context Extension (YaRN)","year":2023,"category":"Efficiency","cat":"Efficiency","origin":"Research community","summary":"YaRN applies frequency-scaled RoPE and attention temperature correction, extending an existing model's context window beyond 128K with little fine-tuning and roughly one tenth the tokens of direct fine-tuning. NTK and LongRoPE continued this line.","impact":"Made long documents, entire codebases and long reasoning chains usable inputs; a key engineering lever in the context-length race.","source":"https://arxiv.org/abs/2309.00071","models":["llama-3-1","deepseek-v4"],"model_refs":["llama-3-1","deepseek-v4"]},{"id":"context-engineering","name":"Context Engineering / Prompt Caching","zh":"Context Engineering / Prompt Caching","year":2024,"category":"Efficiency","cat":"Efficiency","origin":"Anthropic (Prompt Caching, Aug 2024); followed by Google and OpenAI; the term 'Context Engineering' popularized in 2025","summary":"Place stable context (system prompts, tool definitions, long documents) in a prefix and cache its KV computation across requests, while systematically designing what information the model sees.","impact":"Turns context from a one-off consumable into a reusable asset, sharply reducing cost and latency for long-context and agent applications.","source":"https://www.anthropic.com/news/prompt-caching","models":[],"model_refs":[]},{"id":"grpo","name":"GRPO","zh":"Group Relative Policy Optimization","year":2024,"category":"Training","cat":"Training","origin":"DeepSeek","summary":"Shao et al. proposed Group Relative Policy Optimization in DeepSeekMath as a PPO variant: sample a group of answers for one question, estimate advantages from the group's reward mean and standard deviation, and drop the value network of comparable size to the policy.","impact":"Substantially reduces RL memory overhead; the key algorithm behind large-scale RL training of reasoning models such as DeepSeek-R1.","source":"https://arxiv.org/abs/2402.03300","models":["deepseek-r1","deepseek-v2"],"model_refs":["deepseek-r1","deepseek-v2"]},{"id":"graphrag","name":"GraphRAG / Agentic RAG","zh":"GraphRAG / Agentic RAG","year":2024,"category":"Retrieval","cat":"Retrieval","origin":"Microsoft Research (Edge et al.)","summary":"An LLM extracts an entity-relation knowledge graph from the corpus, performs community clustering and pre-generates community summaries, answering global questions in a map-reduce manner.","impact":"Addresses the inability of vector retrieval to answer corpus-wide questions like 'what are the overall themes', pushing RAG toward structure and agency.","source":"https://arxiv.org/abs/2404.16130","models":[],"model_refs":[]},{"id":"kto-orpo-simpo","name":"KTO, ORPO and SimPO Preference Variants","zh":"KTO / ORPO / SimPO","year":2024,"category":"Alignment","cat":"Alignment","origin":"Stanford (Ethayarajh et al.); KAIST; Princeton / UIUC","summary":"KTO needs only binary desirable/undesirable labels rather than paired comparisons; ORPO folds the preference term into SFT and drops the reference model; SimPO uses length-normalized implicit rewards without a reference model.","impact":"Together they lower the data-format and memory barriers of preference alignment, making stable alignment training accessible to smaller teams.","source":"https://arxiv.org/abs/2402.01306","models":[],"model_refs":[]},{"id":"mixture-of-agents","name":"Mixture-of-Agents","zh":"Mixture-of-Agents","year":2024,"category":"Agents","cat":"Agents","origin":"Together AI / University of Chicago / Duke University (Wang et al.)","summary":"Multiple LLMs are arranged in layers: agents at each layer refine their answers using all responses from the previous layer, and a final aggregator synthesizes the output — prompting only, no training.","impact":"An ensemble of open models surpassed GPT-4o on AlpacaEval 2.0, showing model-level ensembling is an effective path to quality.","source":"https://arxiv.org/abs/2406.04692","models":[],"model_refs":[]},{"id":"mla","name":"Multi-head Latent Attention","zh":"Multi-head Latent Attention","year":2024,"category":"Efficiency","cat":"Efficiency","origin":"DeepSeek","summary":"DeepSeek-V2 introduced MLA, jointly compressing multi-head attention Keys/Values into a low-dimensional latent vector before caching, cutting KV cache by over 90% while matching or exceeding standard multi-head attention.","impact":"Greatly reduces inference memory and raises throughput; core to the DeepSeek family's low-cost long-context capability.","source":"https://arxiv.org/abs/2405.04434","models":["deepseek-v2","deepseek-v3","deepseek-r1"],"model_refs":["deepseek-v2","deepseek-v3","deepseek-r1"]},{"id":"online-rl","name":"Online RL / Iterative DPO","zh":"Online RL / Iterative DPO","year":2024,"category":"Alignment","cat":"Alignment","origin":"Google DeepMind (Online DPO / OAIF, Guo, Mesnard et al.)","summary":"Each round samples response pairs from the current model, an LLM annotator gives preferences in real time, and DPO/IPO/SLiC update the policy — avoiding distribution shift from offline preference data.","impact":"Combines DPO's simplicity with on-policy feedback, markedly reducing overfitting; an important direction in iterative alignment.","source":"https://arxiv.org/abs/2402.04792","models":[],"model_refs":[]},{"id":"pd-disaggregation","name":"Prefill/Decode Disaggregation","zh":"Prefill/Decode Disaggregation","year":2024,"category":"Efficiency","cat":"Efficiency","origin":"Peking University / ByteDance et al. (DistServe, Zhong et al.), OSDI 2024","summary":"Deploy the prefill and decode phases of LLM inference on separate GPUs with independently optimized parallelism, eliminating interference so TTFT and TPOT constraints can both be met.","impact":"Significantly improves per-GPU serving throughput and SLO attainment; now a standard architecture option for large-scale inference systems.","source":"https://arxiv.org/abs/2401.09670","models":["DistServe"],"model_refs":[]},{"id":"rlvr","name":"Reinforcement Learning with Verifiable Rewards","zh":"RL with Verifiable Rewards","year":2024,"category":"Training","cat":"Training","origin":"Allen Institute for AI (Tülu 3, coined the term); popularized by DeepSeek (2025)","summary":"Rewards come from verifiers whose correctness is automatically checkable (math answer matching, unit tests, format validation), replacing reward models trained on human preferences.","impact":"Clean reward signals that are hard for models to game; the core training paradigm for o1/R1-style reasoning models.","source":"https://arxiv.org/abs/2411.15124","models":["Tülu 3","DeepSeek-R1","Qwen3"],"model_refs":[]},{"id":"self-rewarding","name":"Self-Rewarding / Self-Improvement","zh":"Self-Rewarding / Self-Improvement","year":2024,"category":"Alignment","cat":"Alignment","origin":"Meta AI + New York University (Yuan et al.)","summary":"A language model scores its own responses via LLM-as-a-Judge, builds preference pairs and improves both instruction following and judging ability in an iterative DPO loop.","impact":"Shows models can self-improve without an external reward model; an important starting point for iterative online alignment.","source":"https://arxiv.org/abs/2401.10020","models":["Llama 2-70B（研究原型）"],"model_refs":[]},{"id":"test-time-compute","name":"Test-time Compute","zh":"Test-time Compute","year":2024,"category":"Reasoning","cat":"Reasoning","origin":"OpenAI","summary":"OpenAI o1 generates a long internal chain of thought before answering and uses RL to train the model to use it effectively; performance grows with both training-time and test-time compute. The GPT-5 family further uses a router to allocate reasoning budget by difficulty.","impact":"Opened a second capability-growth curve beyond pretraining; the main competitive axis for frontier models after 2024.","source":"https://openai.com/index/learning-to-reason-with-llms/","models":["o1","o3","gpt-5","deepseek-r1"],"model_refs":["o1","o3","gpt-5","deepseek-r1"]},{"id":"long-cot","name":"Long CoT / Reasoning Distillation","zh":"Long CoT / Reasoning Distillation","year":2025,"category":"Reasoning","cat":"Reasoning","origin":"DeepSeek（DeepSeek-R1）","summary":"Pure RL or cold-start-plus-RL lets models spontaneously produce long-chain reasoning, self-verification and reflection (the 'aha moment'); these reasoning traces are then distilled into smaller models.","impact":"Showed reasoning ability can be elicited by RL and transferred efficiently, directly triggering the wave of open reasoning models.","source":"https://arxiv.org/abs/2501.12948","models":["DeepSeek-R1","DeepSeek-R1-Distill"],"model_refs":[]}];
